import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(n):
        strings.append(next(iterator))

    try:
        q_count = int(next(iterator))
    except StopIteration:
        q_count = 0

    queries = []
    for _ in range(q_count):
        l = int(next(iterator))
        r = int(next(iterator))
        pattern = next(iterator)
        queries.append((l, r, pattern))

    # Precompute for each unique pattern the list of 1-based indices where it appears
    # Since Q is large and patterns are short, we can cache results per pattern
    pattern_cache = {}

    results = []
    for l, r, pattern in queries:
        if pattern not in pattern_cache:
            indices = []
            for idx, s in enumerate(strings):
                if pattern in s:
                    indices.append(idx + 1)
            pattern_cache[pattern] = indices

        indices = pattern_cache[pattern]
        # Count how many indices are in [l, r]
        # Use binary search for efficiency
        import bisect
        left_idx = bisect.bisect_left(indices, l)
        right_idx = bisect.bisect_right(indices, r)
        count = right_idx - left_idx
        results.append(count)

    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    main()
